import math

def is_power_of_3(n):
    if n <= 0:
        return False
    return (n > 0) and (n & (n - 1) == 0) and (math.log(n, 3) == int(math.log(n, 3)))

def is_power_of_3_simple(n):
    # More robust check for power of 3
    if n <= 0:
        return False
    while n > 1 and n % 3 == 0:
        n //= 3
    return n == 1

def solve_p3(max_b):
    solutions = []
    for a in range(1, max_b + 1):
        for b in range(a, max_b + 1):
            # Check the conditions for p=3
            term1 = a**2 + b
            term2 = b**2 + a

            if is_power_of_3_simple(term1) and is_power_of_3_simple(term2):
                solutions.append((a, b))
    return solutions

# Test up to b=50 for initial exploration
max_b_test = 50
solutions = solve_p3(max_b_test)
print(f"Solutions found for p=3 with b <= {max_b_test}: {solutions}")

# Test up to b=100 just in case
max_b_test_2 = 100
solutions_2 = solve_p3(max_b_test_2)
print(f"Solutions found for p=3 with b <= {max_b_test_2}: {solutions_2}")

